-- Keep organizer documents and payment proofs private and consistent with the
-- event-id-first paths generated by the application.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
	(
		'organizer-documents',
		'organizer-documents',
		false,
		10485760,
		array['application/pdf', 'image/jpeg', 'image/png']::text[]
	),
	(
		'payment-proofs',
		'payment-proofs',
		false,
		10485760,
		array['application/pdf', 'image/jpeg', 'image/png']::text[]
	)
on conflict (id) do update
set public = false,
		file_size_limit = excluded.file_size_limit,
		allowed_mime_types = excluded.allowed_mime_types;

-- Review metadata is staff-managed through the audited RPC below, not a
-- general authenticated column update.
revoke update (verification_status, reviewed_by, reviewed_at)
	on public.event_documents from authenticated;

drop policy "docs_read_owner_or_staff" on storage.objects;
create policy "docs_read_owner_or_staff" on storage.objects
	for select to authenticated
	using (
		bucket_id = 'organizer-documents'
		and (
			exists (
				select 1
				from public.events e
				join public.organizers o on o.id = e.organizer_id
				where e.id::text = (storage.foldername(storage.objects.name))[1]
					and o.owner_id = auth.uid()
			)
			or public.is_staff()
		)
	);

drop policy "docs_upload_owner" on storage.objects;
create policy "docs_upload_owner" on storage.objects
	for insert to authenticated
	with check (
		bucket_id = 'organizer-documents'
		and exists (
			select 1
			from public.events e
			join public.organizers o on o.id = e.organizer_id
			where e.id::text = (storage.foldername(storage.objects.name))[1]
				and o.owner_id = auth.uid()
				and e.status = 'DRAFT'
		)
	);

drop policy "docs_delete_owner" on storage.objects;
create policy "docs_delete_owner" on storage.objects
	for delete to authenticated
	using (
		bucket_id = 'organizer-documents'
		and exists (
			select 1
			from public.events e
			join public.organizers o on o.id = e.organizer_id
			where e.id::text = (storage.foldername(storage.objects.name))[1]
				and o.owner_id = auth.uid()
				and e.status = 'DRAFT'
		)
	);

drop policy "proofs_upload_owner" on storage.objects;
create policy "proofs_upload_owner" on storage.objects
	for insert to authenticated
	with check (
		bucket_id = 'payment-proofs'
		and exists (
			select 1
			from public.events e
			join public.organizers o on o.id = e.organizer_id
			where e.id::text = (storage.foldername(storage.objects.name))[1]
				and o.owner_id = auth.uid()
		)
	);

drop policy "proofs_read_owner_or_staff" on storage.objects;
create policy "proofs_read_owner_or_staff" on storage.objects
	for select to authenticated
	using (
		bucket_id = 'payment-proofs'
		and (
			exists (
				select 1
				from public.events e
				join public.organizers o on o.id = e.organizer_id
				where e.id::text = (storage.foldername(storage.objects.name))[1]
					and o.owner_id = auth.uid()
			)
			or public.is_staff()
		)
	);

create or replace function public.set_event_document_review(
	_document_id uuid,
	_status public.doc_status
)
returns public.event_documents
language plpgsql
security definer
set search_path = ''
as $$
declare
	v_document public.event_documents;
begin
	if auth.uid() is null or not public.is_staff() then
		raise exception 'UNAUTHORIZED';
	end if;

	update public.event_documents
	set verification_status = _status,
			reviewed_by = auth.uid(),
			reviewed_at = now()
	where id = _document_id
	returning * into v_document;

	if not found then
		raise exception 'DOCUMENT_NOT_FOUND';
	end if;

	insert into public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
	values (
		auth.uid(),
		'EVENT_DOCUMENT_REVIEWED',
		'event_document',
		v_document.id,
		jsonb_build_object(
			'verification_status', v_document.verification_status,
			'event_id', v_document.event_id
		)
	);

	return v_document;
end;
$$;

revoke all on function public.set_event_document_review(uuid, public.doc_status)
	from public, anon;
grant execute on function public.set_event_document_review(uuid, public.doc_status)
	to authenticated;
